<script module lang="ts">
/**
 * Picks one node of a hierarchy, in a field (`design/components/tree-select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/popover'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/tree-select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Tree from '../structure/Tree.svelte'
import type { TreeItem, TreeMessages } from '../structure/Tree.svelte'

export interface TreeSelectProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * The branches open at first, while the member holds the set.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * Opens on mount. For galleries and tests; screens let the reader open it.
   */
  defaultOpen?: boolean
  /**
   * The node chosen at first, while the member holds the choice.
   */
  defaultValue?: string
  disabled?: boolean
  /**
   * Labels a selectable empty choice, drawn as the first top-level item. Choosing it reports
   * `null`, and the trigger shows this label as a value.
   */
  emptyOption?: string
  /**
   * The open branches by id. Controlled when given; without it the member holds the set.
   */
  expanded?: ReadonlySet<string>
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  hasMore?: boolean
  id?: string
  invalid?: boolean
  /**
   * Tree's items: the top level, each branch holding the level under it.
   */
  items: TreeItem[]
  /**
   * Names the tree in the popup, as Tree's `label` does: "Organization units". FormField names
   * the field.
   */
  label: string
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  loading?: boolean
  /**
   * Tree's strings, passed to the tree in the popup. Omit for Tree's English defaults.
   */
  messages?: TreeMessages
  /**
   * A hidden field that submits the chosen id, or the empty string for none and the empty
   * choice.
   */
  name?: string
  /**
   * Called with the id of the node a reader chooses, and `null` for the empty choice.
   */
  onChange?: (id: string | null) => void
  /**
   * Called with the next set of open branches, controlled or not.
   */
  onExpandedChange?: (next: ReadonlySet<string>) => void
  /**
   * Called with a branch's id, or `null` for the top level, when a reader asks for more.
   */
  onLoadMore?: (parentId: string | null) => void
  /**
   * Muted, and shown while no node is chosen. Cannot be combined with `emptyOption`.
   */
  placeholder?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem`, as Select's. `'popover'` keeps the
   * anchored popup at every width.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * The chosen node's id. Controlled when given. `null` is no node, and the empty choice when
   * `emptyOption` is set.
   */
  value?: string | null
  /**
   * What the trigger shows while the chosen node is not in `items`, because its level is not
   * loaded. A node in `items` is shown by its own label.
   */
  valueLabel?: string
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultExpanded,
  defaultOpen,
  defaultValue,
  disabled = false,
  emptyOption,
  expanded,
  hasMore = false,
  id: idOwn,
  invalid: invalidOwn = false,
  items,
  label: labelOwn,
  loading = false,
  messages,
  name,
  onChange,
  onExpandedChange,
  onLoadMore,
  placeholder,
  presentation = 'auto',
  size = 'md',
  value,
  valueLabel,
}: TreeSelectProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({
  disabled: disabled,
  label: labelOwn,
  name: name,
  size: size,
}))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let ownValue = $state((defaultValue ?? null) as string | null)
// svelte-ignore state_referenced_locally
let ownExpanded = $state(
  defaultOpen === true
    ? ((
        tops: TreeItem[],
        held: ReadonlySet<string>,
        target: string | null,
      ): ReadonlySet<string> => {
        const walk = (level: TreeItem[], trail: string[]): string[] | null => {
          for (const node of level) {
            if (node.id === target) return trail
            const under =
              node.children === undefined ? null : walk(node.children, [...trail, node.id])
            if (under !== null) return under
          }
          return null
        }
        const above = target === null ? null : walk(tops, [])
        return above === null || above.every((branch) => held.has(branch))
          ? held
          : new Set([...held, ...above])
      })(items, defaultExpanded ?? new Set<string>(), defaultValue ?? null)
    : (defaultExpanded ?? new Set<string>()),
)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
let trigger = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'auto' && phone.current)
const chosen = $derived(value === undefined ? ownValue : value)
const branches = $derived(expanded ?? ownExpanded)
const emptyId = $derived(`${uid}-empty`)
const panelId = $derived(`${uid}-panel`)
const shownItems = $derived(
  emptyOption === undefined ? items : [{ id: emptyId, label: emptyOption }, ...items],
)
const treeValue = $derived(chosen ?? (emptyOption === undefined ? null : emptyId))
const labelOf = $derived((level: TreeItem[], wanted: string): string | undefined => {
  for (const node of level) {
    if (node.id === wanted) return node.label
    const under = node.children === undefined ? undefined : labelOf(node.children, wanted)
    if (under !== undefined) return under
  }
  return undefined
})
const placeholderShown = $derived(chosen === null && emptyOption === undefined)
const shown = $derived(
  chosen === null
    ? (emptyOption ?? placeholder ?? '')
    : (labelOf(items, chosen) ?? valueLabel ?? ''),
)
const changeExpanded = $derived((next: ReadonlySet<string>): void => {
  ownExpanded = next
  onExpandedChange?.(next)
})
const opened = $derived((now: boolean): void => {
  if (!now) return
  const next = ((
    tops: TreeItem[],
    held: ReadonlySet<string>,
    target: string | null,
  ): ReadonlySet<string> => {
    const walk = (level: TreeItem[], trail: string[]): string[] | null => {
      for (const node of level) {
        if (node.id === target) return trail
        const under = node.children === undefined ? null : walk(node.children, [...trail, node.id])
        if (under !== null) return under
      }
      return null
    }
    const above = target === null ? null : walk(tops, [])
    return above === null || above.every((branch) => held.has(branch))
      ? held
      : new Set([...held, ...above])
  })(items, branches, chosen)
  if (next !== branches) changeExpanded(next)
})
const documentDirection = useDirection(() => trigger)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen === true && !disabled,
      modal: true,
      positioning: { placement: 'bottom-start' as const, offset: { mainAxis: 2 } },
      ids: { ...(id === undefined ? {} : { trigger: id }), content: `${uid}-panel` },
      initialFocusEl: () => {
        const box = sheetPanel ?? panel
        return (
          box?.querySelector<HTMLElement>(
            '[role="treeitem"][aria-selected="true"]:not([aria-disabled="true"])',
          ) ??
          box?.querySelector<HTMLElement>('[role="treeitem"]:not([aria-disabled="true"])') ??
          null
        )
      },
      onOpenChange: (details) => {
        opened(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const choose = $derived((picked: string): void => {
  const reported = picked === emptyId ? null : picked
  ownValue = reported
  onChange?.(reported)
  api.setOpen(false)
})
const openFromKeys = $derived((event: KeyboardEvent): void => {
  if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
  event.preventDefault()
  if (!disabled) api.setOpen(true)
})
const closeOnRepick = $derived((event: Event): void => {
  const target = event.target instanceof Element ? event.target : null
  if (target === null) return
  if (event instanceof KeyboardEvent) {
    if (
      (event.key !== 'Enter' && event.key !== ' ') ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey
    )
      return
    if (target.closest('[role="treeitem"]')?.getAttribute('aria-selected') === 'true')
      api.setOpen(false)
    return
  }
  if (target.closest('[data-tree-part="toggle"]') !== null) return
  if (
    target.closest('[data-tree-part="row"]')?.parentElement?.getAttribute('aria-selected') ===
    'true'
  )
    api.setOpen(false)
})
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'TreeSelect',
    element: () => trigger,
    state: () => ({
      value: chosen === null ? (emptyOption === undefined ? null : '') : chosen,
      options: [
        ...(emptyOption === undefined ? [] : [{ id: '', label: emptyOption }]),
        ...((
          level: TreeItem[],
        ): (Pick<TreeItem, 'id' | 'label'> & Partial<Record<'disabled', true>>)[] => {
          const out: (Pick<TreeItem, 'id' | 'label'> & Partial<Record<'disabled', true>>)[] = []
          const walk = (nodes: TreeItem[], off: boolean): void => {
            for (const node of nodes) {
              const shut = off || node.disabled === true
              out.push({
                id: node.id,
                label: node.label,
                ...(shut ? { disabled: true as const } : {}),
              })
              if (node.children !== undefined) walk(node.children, shut)
            }
          }
          walk(level, false)
          return out
        })(items),
      ],
      open: api.open,
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          (value === '' ? null : value) === chosen || choose(value === '' ? emptyId : value),
      },
      open: () => api.setOpen(true),
      close: () => api.setOpen(false),
    },
    withholds: () => sheetPanel ?? panel,
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<button
    bind:this={trigger}
    {...attributes(mergeParts(api.getTriggerProps(), { onKeydown: (event: KeyboardEvent) => { openFromKeys(event) } }))}
    class={styles.trigger}
    role="combobox"
    aria-haspopup="tree"
    aria-controls={api.open ? panelId : undefined}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-required={ariaRequired}
    aria-invalid={(invalid) ? true : undefined}
    disabled={(disabled) ? true : undefined}
    data-size={size}
    data-invalid={(invalid) ? '' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-placeholder={(placeholderShown) ? '' : undefined}
    data-member="tree-select"
    ><span class={styles.value}>{shown}</span
    ><span class={styles.chevron} aria-hidden="true"><Icon name="expand" {size} /></span
  ></button
  >{#if name !== undefined
    }<input type="hidden" {name} value={chosen ?? ''} disabled={(disabled) ? true : undefined}
  />{/if
  }<Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(mergeParts(api.getContentProps(), { onKeydown: (event: KeyboardEvent) => { closeOnRepick(event) }, onClick: (event: MouseEvent) => { closeOnRepick(event) } }))}
          class={styles.content}
          style:--radix-popover-trigger-width={'var(--reference-width)'}
          style:--radix-popover-content-available-width={'var(--available-width)'}
          style:--radix-popover-content-available-height={'var(--available-height)'}
          style:--radix-popover-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          role={undefined}
          aria-modal={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          data-size={size}
          data-member="tree-select"
          ><Tree
            {label}
            items={shownItems}
            expanded={branches}
            value={treeValue}
            {loading}
            {hasMore}
            {messages}
            onChange={(event) => { choose(event) }}
            onExpandedChange={(event) => { changeExpanded(event) }}
            onLoadMore={(event) => { onLoadMore?.(event) }}
        /></div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          {...attributes(api.getContentProps())}
          class={sheet.panel}
          hidden={undefined}
          role={undefined}
          aria-modal={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          data-presentation="sheet"
          ><div
            class={styles.sheetBody}
            data-size={size}
            data-member="tree-select"
            onkeydown={(event) => { closeOnRepick(event) }}
            onclick={(event) => { closeOnRepick(event) }}
            ><Tree
              {label}
              items={shownItems}
              expanded={branches}
              value={treeValue}
              {loading}
              {hasMore}
              {messages}
              onChange={(event) => { choose(event) }}
              onExpandedChange={(event) => { changeExpanded(event) }}
              onLoadMore={(event) => { onLoadMore?.(event) }}
          /></div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
